import React, { useState, useEffect } from 'react';
import './App.css';

function App() {
  // State to hold the list of folder. We'll try to load from localStorage first.
  const [folder, setfolder] = useState(() => {
    const savedfolder = localStorage.getItem('folder');
    return savedfolder ? JSON.parse(savedfolder) : [];
  });

  // State to hold the text of the new folder being entered.
  const [newFolderText, setnewFolderText] = useState('');

  // useEffect hook to save folder to localStorage whenever the folder state changes.
  useEffect(() => {
    localStorage.setItem('folder', JSON.stringify(folder));
  }, [folder]);

  // Function to handle adding a new folder
  const handleAddfolder = (e) => {
    e.preventDefault(); // Prevent form from reloading the page
    if (newFolderText.trim() === '') return; // Don't add empty folder

    const newFolder = {
      id: Date.now(), // Unique ID using timestamp
      text: newFolderText,
      isDone: false,
      progress: 0, // Initial progress is 0
      date: new Date().toLocaleDateString(), // Today's date
    };

    setfolder([...folder, newFolder]);
    setnewFolderText(''); // Clear the input field
  };

  // Function to toggle a folder's 'done' status
  const handleToggleDone = (folderId) => {
    setfolder(folder.map(folder => {
      if (folder.id === folderId) {
        // If folder is marked as done, set progress to 100
        return { ...folder, isDone: !folder.isDone, progress: !folder.isDone ? 100 : folder.progress };
      }
      return folder;
    }));
  };

  // Function to handle changes in the progress slider
  const handleProgressChange = (folderId, newProgress) => {
    setfolder(folder.map(folder => {
      if (folder.id === folderId) {
        // A folder with 100% progress is considered done
        return { ...folder, progress: newProgress, isDone: newProgress === 100 };
      }
      return folder;
    }));
  };

  // Function to delete a folder
  const handleDeletefolder = (folderId) => {
    setfolder(folder.filter(folder => folder.id !== folderId));
  };


  return (
    <div className="app-container">
      <header className="app-header">
        <h1>My folder</h1>
        <p>Stay organized, one folder at a time.</p>
      </header>

      <form onSubmit={handleAddfolder} className="folder-form">
        <input
          type="text"
          value={newFolderText}
          onChange={(e) => setnewFolderText(e.target.value)}
          placeholder="Add a new Folder..."
          className="folder-input"
        />
        <button type="submit" className="add-folder-btn">Add Folder</button>
      </form>

      <div className="folder-list">
        {folder.length > 0 ? (
          folder.map(folder => (
            <div key={folder.id} className={`folder-item ${folder.isDone ? 'done' : ''}`}>
              <div className="folder-content">
                <input
                  type="checkbox"
                  checked={folder.isDone}
                  onChange={() => handleToggleDone(folder.id)}
                  className="folder-checkbox"
                />
                <div className="folder-details">
                  <span className="folder-text">{folder.text}</span>
                  <span className="folder-date">Added: {folder.date}</span>
                </div>
              </div>

              {/* Progress Section: Show only if the folder is NOT done */}
              {!folder.isDone && (
                <div className="progress-container">
                  <input
                    type="range"
                    min="0"
                    max="100"
                    value={folder.progress}
                    onChange={(e) => handleProgressChange(folder.id, parseInt(e.target.value))}
                    className="progress-slider"
                  />
                  <div className="progress-labels">
                    <span>Done: {folder.progress}%</span>
                    <span>Pending: {100 - folder.progress}%</span>
                  </div>
                </div>
              )}

              <button onClick={() => handleDeletefolder(folder.id)} className="delete-btn">
                ×
              </button>
            </div>
          ))
        ) : (
          <p className="no-folder-message">No folder yet. Add one above to get started!</p>
        )}
      </div>
    </div>
  );
}

export default App;
